BEGIN;
CREATE TABLE IF NOT EXISTS express_service_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT false,eligible_service_ids jsonb NOT NULL DEFAULT '[]',service_area_ids jsonb NOT NULL DEFAULT '[]',require_photos boolean NOT NULL DEFAULT false,require_description boolean NOT NULL DEFAULT true,deposit_required boolean NOT NULL DEFAULT false,deposit_amount_cents integer NOT NULL DEFAULT 0,payment_required boolean NOT NULL DEFAULT false,emergency_enabled boolean NOT NULL DEFAULT false,after_hours_enabled boolean NOT NULL DEFAULT false,notifications_enabled boolean NOT NULL DEFAULT true,auto_assign boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(deposit_amount_cents>=0));
CREATE TABLE IF NOT EXISTS express_service_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL,customer_id uuid,portal_account_id uuid,service_id text,property_id text,description text NOT NULL DEFAULT '',urgency text NOT NULL DEFAULT 'normal' CHECK(urgency IN('normal','urgent','emergency')),photos jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','acknowledged','assigned','scheduled','in_progress','completed','invoiced','paid','cancelled')),assigned_technician_id text,converted_job_id text,converted_invoice_id uuid,deposit_payment_id uuid,final_payment_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_esr_tenant ON express_service_requests(tenant_id);
CREATE INDEX IF NOT EXISTS idx_esr_customer ON express_service_requests(tenant_id,customer_id);
CREATE INDEX IF NOT EXISTS idx_esr_status ON express_service_requests(tenant_id,status);
COMMIT;
